_onProductMatched: function (event) {
  const id = event.getParameter("arguments").productId;
  this.getView().bindElement({
    path: "/Products('" + id + "')",
    events: {
      dataReceived: function (dataEvent) {
        if (!dataEvent.getParameter("data")) {
          this.getOwnerComponent().getRouter().getTargets().display("notFound");
        }
      }.bind(this)
    }
  });
}

const routes = {
  "": showHome,
  "products": showProductList
};

function onHashChange() {
  const hash = window.location.hash.replace(/^#\/?/, "");
  const [page, id] = hash.split("/");
  if (page === "products" && id) {
    showProduct(id);           // a route with a parameter
  } else if (routes[page]) {
    routes[page]();
  } else {
    showNotFound();            // like UI5's "bypassed"
  }
}

window.addEventListener("hashchange", onHashChange);
onHashChange(); // like router.initialize(): handle the hash the page was opened with

